(() => {
  const STAMP = '2026-09-16T10:00:00+02:00';
  const FOUR_MONTH_CUTOFF = '2026-05-16';
  const CHECKED_IDS = new Set(['HNR1','EUNL','LHA','ALV']);
  const CHANGED_IDS = new Set(['ALV']);
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const formatStamp = value => new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Berlin',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value)).replace(',', ' ·');
  async function waitForDashboard(){for(let i=0;i<80;i++){try{if(Array.isArray(holdings)&&holdings.length===12&&typeof renderCards==='function'&&typeof renderDetail==='function')return true}catch(_){}await sleep(250)}return false}
  function dedupe(arr){const seen=new Set();return (arr||[]).filter(x=>{const k=`${x.date||''}|${x.title||''}`;if(seen.has(k))return false;seen.add(k);return true})}
  function applyData(){
    window.marketAgentUpdateMeta={contentUpdatedAt:STAMP,lastSuccessfulRunAt:STAMP,status:'partial',marketStatus:'open',holdingsFallback:true};
    holdings.forEach(h=>{if(!CHECKED_IDS.has(h.id))return;h.analysts=(h.analysts||[]).filter(x=>!/^\d{4}-\d{2}-\d{2}$/.test(x.date)||x.date>=FOUR_MONTH_CUTOFF);h.insiders=(h.insiders||[]).filter(x=>!/^\d{4}-\d{2}-\d{2}$/.test(x.date)||x.date>=FOUR_MONTH_CUTOFF);h.lastCheckedAt=STAMP;h.changedSections=[];h.updateStatus='checked';delete h.updateTag});
    const hnr=holdings.find(h=>h.id==='HNR1');if(hnr){hnr.analystNote='Rollierendes Vier-Monats-Fenster ab 16.05.2026, geprüft bis 16.09.2026 10:00 CEST. Hannover-Re-IR sowie ergänzende Analystenquellen geprüft; jüngste verifizierte Einzelrevisionen bleiben Jefferies Buy / 325 EUR vom 09.09.2026, Berenberg Buy / 330 EUR vom 08.09.2026 und Barclays Underweight / 246 EUR vom 04.09.2026.';hnr.insiderNote='Rollierendes Vier-Monats-Fenster ab 16.05.2026 geprüft; keine neue relevante diskretionäre Open-Market-Transaktion verifiziert.';hnr.news=dedupe(hnr.news)}
    const etf=holdings.find(h=>h.id==='EUNL');if(etf){etf.analystNote='Nicht anwendbar: ETF. ISIN IE00B4L5Y983; Analysten- und Insiderfelder sind für ETFs nicht anwendbar.';etf.insiderNote='Nicht anwendbar: Ein ETF hat keine Unternehmensinsider.'}
    const lha=holdings.find(h=>h.id==='LHA');if(lha){lha.analystNote='Rollierendes Vier-Monats-Fenster ab 16.05.2026, geprüft bis 16.09.2026 10:00 CEST. Lufthansa IR und ergänzende Analystenquellen geprüft; seit dem vorherigen EU-Lauf keine neue belastbar verifizierte Einzelrevision.';lha.insiderNote='Directors’ Dealings und ergänzende Quellen im rollierenden Vier-Monats-Fenster geprüft; keine neue diskretionäre Open-Market-Transaktion verifiziert.';lha.news=dedupe(lha.news)}
    const alv=holdings.find(h=>h.id==='ALV');if(alv){alv.news=dedupe([{date:'2026-09-15',sourceName:'EQS / Allianz',category:'Kapitalmaßnahme',title:'Allianz setzt Aktienrückkauf fort',summary:'Allianz meldete für 7.–11. September 2026 den Erwerb von insgesamt 303.283 eigenen Aktien im laufenden Rückkaufprogramm.',impact:1,impactText:'Leicht positiv: Der fortgesetzte Rückkauf reduziert den Streubesitz und stützt ceteris paribus den Gewinn je Aktie; keine Änderung der operativen Prognose.',source:'https://www.allianz.com/en/investor_relations/announcements.html'},...(alv.news||[])]);alv.analystNote='Rollierendes Vier-Monats-Fenster ab 16.05.2026, geprüft bis 16.09.2026 10:00 CEST. Allianz IR und ergänzende Analystenquellen geprüft; keine neue belastbar verifizierte Einzelrevision seit dem vorherigen EU-Lauf.';alv.insiderNote='Rollierendes Vier-Monats-Fenster ab 16.05.2026 geprüft; keine neue diskretionäre Open-Market-Transaktion verifiziert.';alv.lastChangedAt=STAMP;alv.changedSections=['News'];alv.updateStatus='updated';alv.updateTag='NEU'}
  }
  function markUi(){const chip=document.getElementById('content-state-chip'),text=document.getElementById('content-state');if(chip&&text){text.textContent=`Inhalte: ${formatStamp(STAMP)}`;chip.classList.remove('status-ok','status-partial','status-error','status-closed');chip.classList.add('status-partial');chip.title='Holdings-Datei nicht erreichbar – letzter bestätigter Bestand verwendet. EU-/ETF-Inhaltslauf erfolgreich; Teilstatus wegen Holdings-Fallback.'}document.querySelectorAll('.holding').forEach(card=>{card.classList.remove('content-changed','content-partial');if(CHANGED_IDS.has(card.dataset.id))card.classList.add('content-changed');if(CHECKED_IDS.has(card.dataset.id))card.title=`Letzte Inhaltsprüfung: ${formatStamp(STAMP)}${CHANGED_IDS.has(card.dataset.id)?' · Inhalt geändert':' · Keine inhaltliche Änderung'}`});const footer=document.querySelector('footer.shell');if(footer)footer.textContent='Market Agent · Datenstand 16.09.2026 · 10:00 · Quellen in jedem Eintrag'}
  async function boot(){if(!(await waitForDashboard()))return;applyData();renderCards();renderDetail();markUi();[1500,5000,13000,20000].forEach(ms=>setTimeout(()=>{try{renderCards();renderDetail();markUi()}catch(_){}},ms));document.addEventListener('click',e=>{if(e.target.closest('.holding,.tab,.filter'))setTimeout(markUi,0)});window.addEventListener('pageshow',()=>setTimeout(markUi,250))}boot();
})();
